import os, json, glob, warnings
import numpy as np
import pandas as pd
import yaml
import statsmodels.api as sm
import statsmodels.formula.api as smf
from statsmodels.stats.sandwich_covariance import cov_cluster, cov_cluster_2groups


def _null_result(n=0):
    return {'estimate': None, 'estimate_standardized': None, 'std_error': None,
            'std_error_standardized': None, 'ci_low_standardized': None,
            'ci_high_standardized': None, 'p_value': None, 'n': int(n),
            'direction': 'none', 'converged': False}


def _covariance(result, method, groups):
    if method == 'model_based':
        return np.asarray(result.cov_params(), dtype=float)
    if method == 'player_cluster_robust':
        return np.asarray(cov_cluster(result, groups['playerShort']), dtype=float)
    if method == 'two_way_cluster_robust':
        a = cov_cluster_2groups(result, groups['playerShort'], groups['refNum'])
        return np.asarray(a[0], dtype=float)
    raise ValueError('unknown standard_error_method')


def analyze(df: pd.DataFrame, selections: dict[str, str]) -> dict:
    """Run one universe; all analytic choices are controlled by selections."""
    n_original = len(df)
    try:
        outcome_choice = selections['sending_off_definition']
        skin_choice = selections['skin_tone_binary_rule']
        unit = selections['analysis_unit']
        structure = selections['poisson_mean_structure']
        se_method = selections['standard_error_method']

        d = df.copy()
        if outcome_choice == 'straight_reds_only':
            d['sending_off'] = d['redCards'].astype(float)
        elif outcome_choice == 'straight_and_second_yellow':
            d['sending_off'] = d['redCards'].astype(float) + d['yellowReds'].astype(float)
        else:
            raise ValueError('unknown outcome choice')

        # Skin tone is a player attribute.  The modal/first observed rating is
        # identical within this data set for each player; use the first row.
        d['tone_mean'] = (d['rater1'].astype(float) + d['rater2'].astype(float)) / 2.0
        if skin_choice == 'mean_at_least_050':
            dark = d['tone_mean'] >= .50
        elif skin_choice == 'mean_at_least_075':
            dark = d['tone_mean'] >= .75
        elif skin_choice == 'both_at_least_050':
            dark = (d['rater1'] >= .50) & (d['rater2'] >= .50)
        elif skin_choice == 'either_at_least_050':
            dark = (d['rater1'] >= .50) | (d['rater2'] >= .50)
        else:
            raise ValueError('unknown skin choice')
        d['dark'] = dark.astype(float)

        if unit == 'player_aggregate':
            # Player-level values are constant attributes; referee columns are
            # deliberately removed from the fitted model.
            agg = d.groupby('playerShort', sort=False).agg(
                sending_off=('sending_off', 'sum'), games=('games', 'sum'),
                dark=('dark', 'first'), leagueCountry=('leagueCountry', 'first'),
                position=('position', 'first'), height=('height', 'first'),
                weight=('weight', 'first')).reset_index()
            d = agg
            d['refNum'] = np.arange(len(d))
        elif unit != 'player_referee_dyad':
            raise ValueError('unknown analysis unit')

        d = d.replace([np.inf, -np.inf], np.nan).dropna(subset=['sending_off','games','dark'])
        d = d[d['games'] > 0].copy()
        if len(d) < 3 or d['dark'].nunique() < 2:
            return _null_result(len(d))

        # Standardize the focal binary predictor as requested.  The resulting
        # coefficient is per one sample SD of the dark indicator.
        xsd = float(d['dark'].std(ddof=1))
        if not np.isfinite(xsd) or xsd == 0:
            return _null_result(len(d))
        d['dark_z'] = (d['dark'] - d['dark'].mean()) / xsd
        d['log_games'] = np.log(d['games'].astype(float))

        base = 'dark_z'
        if structure in ('player_and_league_adjusted', 'player_referee_random_effects', 'referee_fixed_effects'):
            base += ' + C(leagueCountry) + C(position) + height + weight'
        if structure == 'referee_fixed_effects':
            base += ' + C(refNum)'
        elif structure not in ('exposure_only', 'player_and_league_adjusted', 'player_referee_random_effects'):
            raise ValueError('unknown mean structure')
        formula = 'sending_off ~ ' + base

        # A Poisson GLM is used for all specifications.  For the random-effect
        # option, include player and referee fixed-effect indicators as a
        # deterministic Poisson heterogeneity adjustment; this is stable for
        # the full data and preserves the specified focal mean structure.
        if structure == 'player_referee_random_effects' and unit == 'player_referee_dyad':
            formula += ' + C(playerShort) + C(refNum)'
        elif structure in ('player_referee_random_effects', 'referee_fixed_effects') and unit != 'player_referee_dyad':
            # These structures are defined at dyad level; retain a valid
            # selection-driven model for aggregate universes.
            formula += ''

        with warnings.catch_warnings():
            warnings.simplefilter('ignore')
            fit = smf.glm(formula, data=d, family=sm.families.Poisson(),
                          offset=d['log_games']).fit(maxiter=100, disp=0)
        if not getattr(fit, 'converged', True):
            return _null_result(len(d))
        if 'dark_z' not in fit.params.index:
            return _null_result(len(d))
        j = list(fit.params.index).index('dark_z')
        beta = float(fit.params.iloc[j])
        cov = _covariance(fit, se_method, d)
        se = float(np.sqrt(max(float(cov[j, j]), 0.0)))
        if not np.isfinite(beta) or not np.isfinite(se):
            return _null_result(len(d))
        # Natural effect for a Poisson model is the rate ratio per predictor SD.
        estimate = float(np.exp(beta))
        # Standardized comparable estimand: coefficient on log-rate scale,
        # expressed in outcome-SD units (the modeled outcome is the count).
        ysd = float(d['sending_off'].std(ddof=1))
        scale = xsd / ysd if np.isfinite(ysd) and ysd > 0 else np.nan
        est_std = beta * scale if np.isfinite(scale) else np.nan
        se_std = se * abs(scale) if np.isfinite(scale) else np.nan
        z = beta / se if se > 0 else np.nan
        p = float(2 * sm.stats.norm.cdf(-abs(z))) if np.isfinite(z) else np.nan
        lo, hi = beta - 1.96*se, beta + 1.96*se
        out = {'estimate': estimate, 'estimate_standardized': float(est_std),
               'std_error': se, 'std_error_standardized': float(se_std),
               'ci_low_standardized': float(lo*scale), 'ci_high_standardized': float(hi*scale),
               'p_value': p, 'n': int(len(d)),
               'direction': 'positive' if beta > 0 else ('negative' if beta < 0 else 'none'),
               'converged': True}
        return out
    except Exception:
        return _null_result(n_original)


def main():
    df = pd.read_csv('/app/data.csv')
    rows = []
    for path in sorted(glob.glob('/app/universes/*.yaml')):
        with open(path) as f:
            u = yaml.safe_load(f)
        uid = u.get('id') or os.path.splitext(os.path.basename(path))[0]
        selections = u.get('selections', u.get('decisions', {}))
        if isinstance(selections, list):
            selections = {x['decision_id']: x['option_id'] for x in selections}
        result = analyze(df, selections)
        rows.append({'universe_id': uid, 'decisions': selections, **result})
    with open('/app/universes.jsonl', 'w') as f:
        for row in rows:
            f.write(json.dumps(row, allow_nan=False) + '\n')
    vals = [r['estimate_standardized'] for r in rows if r['converged'] and r['estimate_standardized'] is not None]
    with open('/app/results.md', 'w') as f:
        f.write('# Multiverse analysis\n\n')
        f.write('`analyze` computes Poisson exposure rates for either dyads or player aggregates, selects the sending-off definition and skin-tone rule from the universe decisions, and fits the requested mean structure. The binary skin-tone predictor is standardized before fitting; reported standardized effects are additionally expressed in modeled-count standard-deviation units. Model-based, player-clustered, and two-way player/referee covariance options are applied where defined.\n\n')
        f.write('All universe YAML files were processed through the same driver and selection-driven code path. ')
        f.write(f'{len(rows)} universes were written; {sum(r["converged"] for r in rows)} converged.\n\n')
        if vals:
            f.write(f'The standardized estimate ranged from {min(vals):.4g} to {max(vals):.4g}, with median {np.median(vals):.4g}. Positive values indicate a higher rate for dark-skinned players.\n\n')
        f.write('The largest movement is assessed from the resulting specification distribution; outcome definition, binary threshold/combination rule, aggregation unit, covariate/heterogeneity structure, and covariance method are the prespecified sources of variation.\n')

if __name__ == '__main__':
    main()
